    None = 0,
    Top = 1,
    Bottom = 2,
    Left = 4,
    TopLeft = 5,
    BottomLeft = 6,
    Right = 8,
    TopRight = 9,
    BottomRight = 10,
}

/// <summary>Types of state on the surface</summary>
/// <remarks>
/// The different state values used on the surface. This is designed for
/// state values like maximized, fullscreen. It is paired with the
/// configure event to ensure that both the client and the compositor
/// setting the state can be synchronized.
/// <para/>
/// States set in this way are double-buffered, see wl_surface.commit.
/// </remarks>
public enum XdgToplevelState : uint
{
    /// <summary>the surface is maximized</summary>
    Maximized = 1,
    /// <summary>the surface is fullscreen</summary>
    Fullscreen = 2,
    /// <summary>the surface is being resized</summary>
    Resizing = 3,
    /// <summary>the surface is now activated</summary>
    Activated = 4,
    TiledLeft = 5,
    TiledRight = 6,
    TiledTop = 7,
    TiledBottom = 8,
    Suspended = 9,
    ConstrainedLeft = 10,
    ConstrainedRight = 11,
    ConstrainedTop = 12,
    ConstrainedBottom = 13,
}

public enum XdgToplevelWmCapabilities : uint
{
    /// <summary>show_window_menu is available</summary>
    WindowMenu = 1,
    /// <summary>set_maximized and unset_maximized are available</summary>
    Maximize = 2,
    /// <summary>set_fullscreen and unset_fullscreen are available</summary>
    Fullscreen = 3,
    /// <summary>set_minimized is available</summary>
    Minimize = 4,
}

/// <summary>Short-lived, popup surfaces for menus</summary>
/// <remarks>
/// A popup surface is a short-lived, temporary surface. It can be used to
/// implement for example menus, popovers, tooltips and other similar user
/// interface concepts.
/// <para/>
/// A popup can be made to take an explicit grab. See xdg_popup.grab for
/// details.
/// <para/>
/// When the popup is dismissed, a popup_done event will be sent out, and at
/// the same time the surface will be unmapped. See the xdg_popup.popup_done
/// event for details.
/// <para/>
/// Explicitly destroying the xdg_popup object will also dismiss the popup and
/// unmap the surface. Clients that want to dismiss the popup when another
/// surface of their own is clicked should dismiss the popup using the destroy
/// request.
/// <para/>
/// A newly created xdg_popup will be stacked on top of all previously created
/// xdg_popup surfaces associated with the same xdg_toplevel.
/// <para/>
/// The parent of an xdg_popup must be mapped (see the xdg_surface
/// description) before the xdg_popup itself.
/// <para/>
/// The client must call wl_surface.commit on the corresponding wl_surface
/// for the xdg_popup state to take effect.
/// </remarks>
public sealed unsafe partial class XdgPopup : WlProxy, IWaylandProxy<XdgPopup>
{
    public static string InterfaceName => "xdg_popup";
    public static uint MaxVersion => 7;
    public static WlInterface* NativeInterface => WaylandInterfaces.xdg_popup;
    public static XdgPopup Wrap(nint handle) => new(handle);

    private XdgPopup(nint handle) : base(handle) { }

    /// <summary>Sends <c>destroy</c>, then destroys the proxy.</summary>
    protected override void Destroy()
    {
        Marshal(0, null, 1, "destroy", destroy: true);
    }

    /// <summary>Make the popup take an explicit grab</summary>
    /// <remarks>
    /// This request makes the created popup take an explicit grab. An explicit
    /// grab will be dismissed when the user dismisses the popup, or when the
    /// client destroys the xdg_popup. This can be done by the user clicking
    /// outside the surface, using the keyboard, or even locking the screen
    /// through closing the lid or a timeout.
    /// <para/>
    /// If the compositor denies the grab, the popup will be immediately
    /// dismissed.
    /// <para/>
    /// This request must be used in response to some sort of user action like a
    /// button press, key press, or touch down event. The serial number of the
    /// event should be passed as 'serial'.
    /// <para/>
    /// The parent of a grabbing popup must either be an xdg_toplevel surface or
    /// another xdg_popup with an explicit grab. If the parent is another
    /// xdg_popup it means that the popups are nested, with this popup now being
    /// the topmost popup.
    /// <para/>
    /// Nested popups must be destroyed in the reverse order they were created
    /// in, e.g. the only popup you are allowed to destroy at all times is the
    /// topmost one.
    /// <para/>
    /// When compositors choose to dismiss a popup, they may dismiss every
    /// nested grabbing popup as well. When a compositor dismisses popups, it
    /// will follow the same dismissing order as required from the client.
    /// <para/>
    /// If the topmost grabbing popup is destroyed, the grab will be returned to
    /// the parent of the popup, if that parent previously had an explicit grab.
    /// <para/>
    /// If the parent is a grabbing popup which has already been dismissed, this
    /// popup will be immediately dismissed. If the parent is a popup that did
    /// not take an explicit grab, an error will be raised.
    /// <para/>
    /// During a popup grab, the client owning the grab will receive pointer
    /// and touch events for all their surfaces as normal (similar to an
    /// "owner-events" grab in X11 parlance), while the top most grabbing popup
    /// will always have keyboard focus.
    /// </remarks>
    /// <param name="seat">the wl_seat of the user event</param>
    /// <param name="serial">the serial of the user event</param>
    public void Grab(WlSeat seat, uint serial)
    {
        WlArgument* args = stackalloc WlArgument[2];
        args[0].o = WlProxy.HandleOf(seat);
        args[1].u = serial;
        Marshal(1, args, 1, "grab");
    }

    /// <summary>Recalculate the popup's location</summary>
    /// <remarks>
    /// Reposition an already-mapped popup. The popup will be placed given the
    /// details in the passed xdg_positioner object, and a
    /// xdg_popup.repositioned followed by xdg_popup.configure and
    /// xdg_surface.configure will be emitted in response. Any parameters set
    /// by the previous positioner will be discarded.
    /// <para/>
    /// The passed token will be sent in the corresponding
    /// xdg_popup.repositioned event. The new popup position will not take
    /// effect until the corresponding configure event is acknowledged by the
    /// client. See xdg_popup.repositioned for details. The token itself is
    /// opaque, and has no other special meaning.
    /// <para/>
    /// If multiple reposition requests are sent, the compositor may skip all
    /// but the last one.
    /// <para/>
    /// If the popup is repositioned in response to a configure event for its
    /// parent, the client should send an xdg_positioner.set_parent_configure
    /// and possibly an xdg_positioner.set_parent_size request to allow the
    /// compositor to properly constrain the popup.
    /// <para/>
    /// If the popup is repositioned together with a parent that is being
    /// resized, but not in response to a configure event, the client should
    /// send an xdg_positioner.set_parent_size request.
    /// <para>Since version 3.</para>
    /// </remarks>
    /// <param name="token">reposition request token</param>
    public void Reposition(XdgPositioner positioner, uint token)
    {
        WlArgument* args = stackalloc WlArgument[2];
        args[0].o = WlProxy.HandleOf(positioner);
        args[1].u = token;
        Marshal(2, args, 3, "reposition");
    }

    /// <summary>Configure the popup surface</summary>
    /// <remarks>
    /// This event asks the popup surface to configure itself given the
    /// configuration. The configured state should not be applied immediately.
    /// See xdg_surface.configure for details.
    /// <para/>
    /// The x and y arguments represent the position the popup was placed at
    /// given the xdg_positioner rule, relative to the upper left corner of the
    /// window geometry of the parent surface.
    /// <para/>
    /// For version 2 or older, the configure event for an xdg_popup is only
    /// ever sent once for the initial configuration. Starting with version 3,
    /// it may be sent again if the popup is setup with an xdg_positioner with
    /// set_reactive requested, or in response to xdg_popup.reposition requests.
    /// </remarks>
    public event Action<XdgPopupConfigureEvent>? Configure;

    /// <summary>Popup interaction is done</summary>
    /// <remarks>
    /// The popup_done event is sent out when a popup is dismissed by the
    /// compositor. The client should destroy the xdg_popup object at this
    /// point.
    /// </remarks>
    public event Action? PopupDone;

    /// <summary>Signal the completion of a repositioned request</summary>
    /// <remarks>
    /// The repositioned event is sent as part of a popup configuration
    /// sequence, together with xdg_popup.configure and lastly
    /// xdg_surface.configure to notify the completion of a reposition request.
    /// <para/>
    /// The repositioned event is to notify about the completion of a
    /// xdg_popup.reposition request. The token argument is the token passed
    /// in the xdg_popup.reposition request.
    /// <para/>
    /// Immediately after this event is emitted, xdg_popup.configure and
    /// xdg_surface.configure will be sent with the updated size and position,
    /// as well as a new configure serial.
    /// <para/>
    /// The client should optionally update the content of the popup, but must
    /// acknowledge the new popup configuration for the new position to take
    /// effect. See xdg_surface.ack_configure for details.
    /// <para>Since version 3.</para>
    /// </remarks>
    public event Action<XdgPopupRepositionedEvent>? Repositioned;

    protected override void Dispatch(uint opcode, WlArgument* args)
    {
        switch (opcode)
        {
            case 0:
                Configure?.Invoke(new XdgPopupConfigureEvent(args));
                break;
            case 1:
                PopupDone?.Invoke();
                break;
            case 2:
                Repositioned?.Invoke(new XdgPopupRepositionedEvent(args));
                break;
        }
    }
}

/// <summary>Arguments of <see cref="XdgPopup"/>'s <c>configure</c> event. Only valid during the event handler.</summary>
public readonly unsafe ref struct XdgPopupConfigureEvent
{
    readonly WlArgument* args;

    internal XdgPopupConfigureEvent(WlArgument* args) => this.args = args;

    /// <summary>x position relative to parent surface window geometry</summary>
    public int X => args[0].i;

    /// <summary>y position relative to parent surface window geometry</summary>
    public int Y => args[1].i;

    /// <summary>window geometry width</summary>
    public int Width => args[2].i;

    /// <summary>window geometry height</summary>
    public int Height => args[3].i;
}

/// <summary>Arguments of <see cref="XdgPopup"/>'s <c>repositioned</c> event. Only valid during the event handler.</summary>
public readonly unsafe ref struct XdgPopupRepositionedEvent
{
    readonly WlArgument* args;

    internal XdgPopupRepositionedEvent(WlArgument* args) => this.args = args;

    /// <summary>reposition request token</summary>
    public uint Token => args[0].u;
}

public enum XdgPopupError : uint
{
    /// <summary>tried to grab after being mapped</summary>
    InvalidGrab = 0,
}
